-- =====================================================================
-- Ultraclínica RSL · ZERA O BANCO e carrega dados FICTÍCIOS
-- ATENÇÃO: apaga TODOS os dados (tabelas records e settings) e TODOS os usuários
-- do Supabase Auth. Rode antes o supabase/schema.sql atualizado (função is_owner).
-- Como usar: Supabase > SQL Editor > New query > cole TUDO > Run.
-- Datas são relativas ao dia em que você rodar (dias úteis para a agenda).
-- =====================================================================

do $$ begin
  if to_regprocedure('public.is_owner()') is null then
    raise exception 'Rode primeiro o schema.sql atualizado (falta a função is_owner).';
  end if;
end $$;

create extension if not exists pgcrypto with schema extensions;

-- auxiliar: troca @B-3@ (3 dias úteis atrás), @D10@ (daqui a 10 dias), @B-3p30@ (+30 dias) por datas
create or replace function public._seed_fix(t text) returns text language plpgsql as $f$
declare m text[]; r text := t; d date; n int; k int; s int;
begin
  for m in select regexp_matches(t, '@([BD])(-?[0-9]+)(?:([pm])([0-9]+))?@', 'g') loop
    n := m[2]::int;
    if m[1] = 'D' then
      d := current_date + n;
    else
      d := current_date; s := case when n < 0 then -1 else 1 end; k := abs(n);
      while k > 0 loop
        d := d + s;
        if extract(isodow from d) < 6 then k := k - 1; end if;
      end loop;
    end if;
    if m[3] = 'p' then d := d + m[4]::int; elsif m[3] = 'm' then d := d - m[4]::int; end if;
    r := replace(r, '@' || m[1] || m[2] || coalesce(m[3] || m[4], '') || '@', to_char(d, 'YYYY-MM-DD'));
  end loop;
  return r;
end $f$;

-- 1) ZERAR
truncate table public.records restart identity;
truncate table public.settings;
delete from auth.users;   -- apaga também os perfis (cascade)

-- 2) USUÁRIOS (e-mail / senha / nome / tipo de acesso / médico / clínicas)
